const seen = new Set();
return $input.all().filter(item => {
  const j = item.json || {};
  const url = j.link || j.guid || "";
  if (!url || seen.has(url)) return false;
  seen.add(url);
  const text = ((j.title || "") + " " + (j.contentSnippet || j.content || "")).toLowerCase();
  const keywords = ["ai","artificial intelligence","machine learning","neural","brain","health","medical","medicine","aging","ageing","longevity","biomedical","robot","public health","neuroscience"];
  if (!keywords.some(k => text.includes(k))) return false;
  item.json.lifeos = {
    source: "MIT News",
    url,
    title: j.title || "MIT News",
    published_at: j.isoDate || j.pubDate || null,
    collected_at: new Date().toISOString(),
    country: "США",
    tags: ["MIT"]
  };
  return true;
});

